// Fictional sample images for the Images screen (ADR 0005). Specimen-style documents from
// eval/fixtures/visual/ (LAB-1121): the faces, signatures, stamp and textures were generated by
// Muse Image and belong to no one; every name and number is made up and laid out by
// eval/visual/generate_images.py (the IDs pass their checksums but are fictional). Each is
// overprinted MINTA / SPECIMEN. The demo engine replays regions recorded for exactly these files.

export interface ImageSample {
  id: string;
  title: string;
  subtitle: string;
  /** Language of the printed text: decides which rules run on its OCR text. */
  language: "hu" | "en";
  src: string;
  thumbnail: string;
  width: number;
  height: number;
  alt: string;
}

